# ================================================================ 落盘
def main():
    if not os.path.isdir(OUT_DIR):
        os.makedirs(OUT_DIR)
    ids = [q["id"] for q in QUESTIONS]
    assert len(ids) >= 6, "主观题至少要成批（6 道起）"
    assert len(set(ids)) == len(ids), "草稿 id 重复"
    cats = [q["category"] for q in QUESTIONS]
    # 三个类别必须等量：出题最容易悄悄偏科的就是"system-design 好写所以多写两道"
    per_cat = {c: cats.count(c) for c in ("system-design", "agent-design", "hot-interviews")}
    assert len(per_cat) == 3 and len(set(per_cat.values())) == 1, "类别配比要三等：%s" % per_cat
    diffs = [q["difficulty"] for q in QUESTIONS]
    assert diffs.count("principal") * 3 >= len(diffs), "principal 少于三分之一：这批在往下降难度"
    for q in QUESTIONS:
        pts = q["rubric"]["points"]
        assert len(pts) >= 3, "%s 考点太少" % q["id"]
        assert sum(p["weight"] for p in pts) == q["rubric"]["maxScore"], "%s 权重合计不是 10" % q["id"]
        assert q["judgeKind"] == "llm-rubric" and "cases" not in q, "%s 主观题不许带 cases" % q["id"]
        assert 1 <= len(q["tags"]) <= 6, "%s 标签数量不合规" % q["id"]
        for tag in q["tags"]:
            assert TAG_RE.match(tag), "%s 标签不合规 %s" % (q["id"], tag)
        assert q["source"]["company"] == "Alibaba", "%s 必须带来源公司" % q["id"]
        # 短字段是用 ASCII 双引号包住的 Python 字面量，里面再出现 ASCII 双引号会直接炸语法；
        # 长文本块用三引号，里面的引号由 json.dump 负责转义（素材原文就是 ccl_queue_filed("id")）。
        for short in [q["title"]] + [p["criteria"] + p["label"] for p in pts] + [q["rubric"].get("notes", "")]:
            assert '"' not in short, "短字段里出现了 ASCII 双引号：%s" % short[:40]
        assert "用例「" not in q["statement"] + q["answer"], "%s 出现了像用例名的引号标题" % q["id"]
        path = os.path.join(OUT_DIR, "%s.json" % q["id"])
        # 文件名带 id（方便逐题 bank:add 看"新增 1"），但**草稿本体不带 id** ——
        # id 是入库时按类别顺序分配的，草稿里写死会让"生成器 ↔ 题库"逐字段比对多出一个字段，
        # 于是那道审计（check_provenance.py）在别的公司能过、在这里永远漂。
        payload = {k: v for k, v in q.items() if k not in ("id", "schemaVersion")}
        with io.open(path, "w", encoding="utf-8", newline="\n") as f:
            json.dump(payload, f, ensure_ascii=False, indent=2)
            f.write("\n")
        # 落盘后读回来比对：内层引号毁掉 JSON 是本仓库出过的真实事故（三个"静默降级"缺陷之一），
        # 所以这里不信"写出去了"，只信"读回来还一样"。
        with io.open(path, "r", encoding="utf-8") as f:
            assert json.load(f) == payload, "%s 生成的 JSON 读回来与原对象不一致" % q["id"]
        print("wrote %s（%s / %s）" % (os.path.relpath(path, ROOT), q["category"], q["difficulty"]))


if __name__ == "__main__":
    main()
